local owner, elder = {}, { ["Elder Bellowrage"] = true, ["Elder Bladeleaf"] = true, ["Elder Bladesing"] = true, ["Elder Bladeswift"] = true, ["Elder Bloodhoof"] = true, ["Elder Brightspear"] = true, ["Elder Bronzebeard"] = true, ["Elder Darkcore"] = true, ["Elder Darkhorn"] = true, ["Elder Dawnstrider"] = true, ["Elder Dreamseer"] = true, ["Elder Farwhisper"] = true, ["Elder Goldwell"] = true, ["Elder Graveborn"] = true, ["Elder Grimtotem"] = true, ["Elder Hammershout"] = true, ["Elder High Mountain"] = true, ["Elder Highpeak"] = true, ["Elder Ironband"] = true, ["Elder Meadowrun"] = true, ["Elder Mistwalker"] = true, ["Elder Moonstrike"] = true, ["Elder Moonwarden"] = true, ["Elder Morndeep"] = true, ["Elder Morningdew"] = true, ["Elder Nightwind"] = true, ["Elder Obsidian"] = true, ["Elder Primestone"] = true, ["Elder Proudhorn"] = true, ["Elder Ragetotem"] = true, ["Elder Riversong"] = true, ["Elder Rumblerock"] = true, ["Elder Runetotem"] = true, ["Elder Silvervein"] = true, ["Elder Skychaser"] = true, ["Elder Skygleam"] = true, ["Elder Skyseer"] = true, ["Elder Snowcrown"] = true, ["Elder Splitrock"] = true, ["Elder Starglade"] = true, ["Elder Starsong"] = true, ["Elder Starweave"] = true, ["Elder Stonefort"] = true, ["Elder Stonespire"] = true, ["Elder Stormbrow"] = true, ["Elder Thunderhorn"] = true, ["Elder Wildmane"] = true, ["Elder Windrun"] = true, ["Elder Windtotem"] = true, ["Elder Winterhoof"] = true }
RG.ARCADE_HOLIDAY_OF = owner
for _, d in ipairs(RG.ARCADE_HOLIDAYS) do RG.ARCADE_DUNGEONS[#RG.ARCADE_DUNGEONS + 1] = d; for _, n in ipairs(d[5]) do owner[n] = owner[n] or d[1] end end
for _, r in ipairs(RG.ARCADE_HOLIDAY_ROWS) do r[6] = owner[r[2]]; r[7] = elder[r[2]]; r[8] = true; RG.ARCADE_DATA[#RG.ARCADE_DATA + 1] = r end
RG.ARCADE_NPC = RG.ARCADE_NPC or {}
for k, v in pairs(RG.ARCADE_HOLIDAY_NPC) do if not RG.ARCADE_NPC[k] then RG.ARCADE_NPC[k] = v end end
RG.ARCADE_DUNGEON_CREATURE = RG.ARCADE_DUNGEON_CREATURE or {}
for k, v in pairs(RG.ARCADE_HOLIDAY_CREATURE) do if not RG.ARCADE_DUNGEON_CREATURE[k] then RG.ARCADE_DUNGEON_CREATURE[k] = v end end
